#"'!/usr/bin/env python3
"""OpenAI Responses API client using only the standard library."""

import json
import ssl
import urllib.request
import urllib.error


class OpenAIClient:
    """Client for OpenAI Responses API using only standard library."""

    def __init__(self, api_key: str, base_url: str = "https://api.openai.com/v1"):
        self.api_key = api_key
        self.base_url = base_url.rstrip("/")
        self._session = ssl.create_default_context()

    def _request(self, method: str, endpoint: str, **kwargs) -> dict:
        """Make an HTTP request to the OpenAI API."""
        url = f"{self.base_url}{endpoint}"
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        body = kwargs.pop("body", None)
        if body is not None:
            headers["Content-Length"] = str(len(body))
            request = urllib.request.Request(
                url, data=body, method=method, headers=headers
            )
        else:
            request = urllib.request.Request(
                url, method=method, headers=headers
            )

        # Set custom headers from kwargs
        for key, value in kwargs.get("headers", {}).items():
            request.add_header(key, value)

        try:
            with urllib.request.urlopen(request, context=self._session) as response:
                return json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8")
            raise OpenAIError(e.code, f"OpenAI API error: {body}") from e

    def respond(self, prompt: str, model: str = "gpt-4o-mini", **kwargs) -> dict:
        """Send a text prompt to the Responses API and return the response."""
        body = json.dumps(
            {"input": prompt, "model": model, **kwargs}
        ).encode("utf-8")
        return self._request("POST", "/responses", body=body)

    def close(self):
        """Close any open resources."""
        pass


